--
-- Name: calculate_check_totals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_check_totals(_check_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE public.order_checks
  SET 
    subtotal = COALESCE((
      SELECT SUM(subtotal) FROM public.order_items WHERE check_id = _check_id
    ), 0),
    tax = COALESCE((
      SELECT SUM(tax) FROM public.order_items WHERE check_id = _check_id
    ), 0),
    discounts = COALESCE((
      SELECT SUM(discounts) FROM public.order_items WHERE check_id = _check_id
    ), 0),
    total = COALESCE((
      SELECT SUM(subtotal + tax - discounts) FROM public.order_items WHERE check_id = _check_id
    ), 0)
  WHERE id = _check_id;
END;
$$;


ALTER FUNCTION public.calculate_check_totals(_check_id uuid) OWNER TO postgres;

--
-- Name: calculate_order_totals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_order_totals(_order_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  _subtotal numeric;
  _tax numeric;
  _discounts numeric;
  _service_fee numeric;
  _total numeric;
BEGIN
  SELECT 
    COALESCE(SUM(subtotal), 0),
    COALESCE(SUM(tax), 0),
    COALESCE(SUM(discounts), 0)
  INTO _subtotal, _tax, _discounts
  FROM public.order_items
  WHERE order_id = _order_id;
  
  -- Obtener service_fee si aplica
  SELECT COALESCE(service_fee, 0) INTO _service_fee
  FROM public.orders WHERE id = _order_id;
  
  _total := _subtotal + _tax + _service_fee - _discounts;
  
  UPDATE public.orders
  SET 
    subtotal = _subtotal,
    tax = _tax,
    discounts = _discounts,
    total = _total
  WHERE id = _order_id;
END;
$$;


ALTER FUNCTION public.calculate_order_totals(_order_id uuid) OWNER TO postgres;

--
-- Name: consume_inventory_from_order(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_inventory_from_order(_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  oi record;
  ri record;
begin
  for oi in
    select * from public.order_items where order_id = _order_id
  loop
    for ri in
      select r.id as recipe_id, i.inventory_item_id, i.quantity
      from public.recipes r
      join public.recipe_ingredients i on i.recipe_id = r.id
      where r.menu_item_id = oi.product_id
    loop
      insert into public.inventory_movements (
        business_id, warehouse_id, item_id,
        movement_type, quantity, reference_id, reference_type
      )
      select
        oi.business_id,
        w.id,
        ri.inventory_item_id,
        'sale',
        -(ri.quantity * oi.quantity),
        oi.order_id,
        'order'
      from public.warehouses w
      where w.business_id = oi.business_id and w.is_main = true;
    end loop;
  end loop;
end;
$$;


ALTER FUNCTION public.consume_inventory_from_order(_order_id uuid) OWNER TO postgres;

--
-- Name: create_business_defaults(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_business_defaults(_business_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $_$
begin
  insert into public.payment_methods (business_id, name, code, position, icon)
  select _business_id, 'Efectivo', 'cash', 1, 'banknote'
  where not exists (
    select 1 from public.payment_methods pm
    where pm.business_id = _business_id and pm.code = 'cash'
  );

  insert into public.payment_methods (business_id, name, code, position, icon)
  select _business_id, 'Tarjeta', 'card', 2, 'credit-card'
  where not exists (
    select 1 from public.payment_methods pm
    where pm.business_id = _business_id and pm.code = 'card'
  );

  insert into public.payment_methods (business_id, name, code, position, icon)
  select _business_id, 'Transferencia', 'transfer', 3, 'building-2'
  where not exists (
    select 1 from public.payment_methods pm
    where pm.business_id = _business_id and pm.code = 'transfer'
  );

  insert into public.currencies (business_id, code, name, symbol, is_default)
  select _business_id, 'DOP', 'Peso Dominicano', 'RD$', true
  where exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'currencies'
  )
  and not exists (
    select 1 from public.currencies c
    where c.business_id = _business_id and c.is_default = true
  );

  insert into public.business_settings (
    business_id,
    default_tax_rate,
    service_fee_enabled,
    service_fee_rate
  )
  select _business_id, 18, true, 10
  where not exists (
    select 1 from public.business_settings bs where bs.business_id = _business_id
  );

  update public.business_settings
     set service_fee_enabled = true
   where business_id = _business_id
     and service_fee_enabled is distinct from true;

  insert into public.taxes (business_id, name, rate)
  select _business_id, 'ITBIS', 18
  where not exists (
    select 1 from public.taxes t
    where t.business_id = _business_id and lower(t.name) = lower('ITBIS')
  );

  insert into public.zones (business_id, name, sort_index)
  select _business_id, 'Salon Principal', 1
  where not exists (
    select 1 from public.zones z
    where z.business_id = _business_id and lower(z.name) = lower('Salon Principal')
  );

  if exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'warehouses'
  ) then
    insert into public.warehouses (business_id, name, is_main)
    select _business_id, 'Almacen Principal', true
    where not exists (
      select 1 from public.warehouses w
      where w.business_id = _business_id and w.is_main = true
    );
  end if;

  insert into public.menus (id, business_id, name, is_active, created_at)
  select gen_random_uuid(), _business_id, 'Menú Principal', true, now()
  where not exists (
    select 1 from public.menus m where m.business_id = _business_id
  );

  if not exists (
    select 1 from public.categories c where c.business_id = _business_id
  ) then
    insert into public.categories (id, business_id, name, position, is_active, created_at)
    values
      (gen_random_uuid(), _business_id, 'Bebidas', 1, true, now()),
      (gen_random_uuid(), _business_id, 'Entradas', 2, true, now()),
      (gen_random_uuid(), _business_id, 'Platos Fuertes', 3, true, now()),
      (gen_random_uuid(), _business_id, 'Postres', 4, true, now());
  end if;
end;
$_$;


ALTER FUNCTION public.create_business_defaults(_business_id uuid) OWNER TO postgres;

