--

CREATE FUNCTION public.enforce_prep_minutes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.has_prep = false then
    NEW.prep_minutes := 0;
  else
    NEW.prep_minutes := greatest(0, coalesce(NEW.prep_minutes,0));
  end if;
  return NEW;
end;
$$;


