--
-- Name: fn_add_item_from_menu(uuid, uuid, numeric, integer, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_add_item_from_menu(p_order_id uuid, p_menu_item_id uuid, p_qty numeric DEFAULT 1, p_check_position integer DEFAULT 1, p_is_takeout boolean DEFAULT false, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_name text;
  v_price numeric(12,2);
  v_check uuid;
  v_item_id uuid;
  v_qty numeric(10,3);
begin
  v_qty := greatest(coalesce(p_qty, 1), 1);

  select name, price
    into v_name, v_price
  from public.menu_items
  where id = p_menu_item_id
  limit 1;

  if v_name is null then
    raise exception 'MENU_ITEM_NOT_FOUND';
  end if;

  v_check := public.fn_get_or_create_check(p_order_id, p_check_position);

  insert into public.order_items(
    order_id, check_id, product_id, product_name,
    qty, quantity, unit_price, is_takeout, notes, status
  ) values (
    p_order_id, v_check, p_menu_item_id, v_name,
    v_qty, v_qty, v_price, coalesce(p_is_takeout, false), p_notes, 'draft'
  )
  returning id into v_item_id;

  perform public.fn_recalc_order_totals(p_order_id);
  return v_item_id;
end;
$$;


ALTER FUNCTION public.fn_add_item_from_menu(p_order_id uuid, p_menu_item_id uuid, p_qty numeric, p_check_position integer, p_is_takeout boolean, p_notes text) OWNER TO postgres;

