--
-- Name: fn_assign_customer_to_session(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_customer_to_session(p_session_id uuid, p_customer_id uuid, p_customer_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_customer_name text;
begin
  select ts.business_id
    into v_business_id
  from public.table_sessions ts
  where ts.id = p_session_id;

  if v_business_id is null then
    raise exception 'SESSION_NOT_FOUND';
  end if;

  if auth.uid() is not null
     and not public.user_has_business_access(auth.uid(), v_business_id) then
    raise exception 'ACCESS_DENIED';
  end if;

  if p_customer_id is not null then
    select c.name
      into v_customer_name
    from public.customers c
    where c.id = p_customer_id
      and c.business_id = v_business_id;

    if v_customer_name is null then
      raise exception 'CUSTOMER_NOT_FOUND';
    end if;
  end if;

  update public.table_sessions
     set customer_id = p_customer_id,
         customer_name = coalesce(
           nullif(trim(coalesce(p_customer_name, '')), ''),
           v_customer_name
         )
   where id = p_session_id;
end;
$$;


ALTER FUNCTION public.fn_assign_customer_to_session(p_session_id uuid, p_customer_id uuid, p_customer_name text) OWNER TO postgres;

--
-- Name: fn_assign_manual_order_to_table(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_manual_order_to_table(p_order_id uuid, p_table_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_source_session_id uuid;
  v_source_origin public.order_origin;
  v_source_people integer;
  v_source_opened_by uuid;
  v_source_waiter uuid;
  v_source_customer_id uuid;
  v_source_customer_name text;
  v_source_table_id uuid;

  v_order_status public.order_status;
  v_order_closed_at timestamptz;

  v_target_business_id uuid;
  v_existing_target_session uuid;
  v_existing_open_orders bigint := 0;

  v_new_session_id uuid;
  v_remaining_source_open_orders bigint := 0;
begin
  if auth.uid() is not null and p_user_id is not null and p_user_id <> auth.uid() then
    raise exception 'INVALID_USER_CONTEXT';
  end if;

  v_user_id := coalesce(auth.uid(), p_user_id);

  select
    o.session_id,
    o.status_ext,
    o.closed_at,
    ts.origin,
    ts.people_count,
    ts.opened_by,
    ts.waiter_user_id,
    ts.customer_id,
    ts.customer_name,
    ts.table_id
  into
    v_source_session_id,
    v_order_status,
    v_order_closed_at,
    v_source_origin,
    v_source_people,
    v_source_opened_by,
    v_source_waiter,
    v_source_customer_id,
    v_source_customer_name,
    v_source_table_id
  from public.orders o
  join public.table_sessions ts on ts.id = o.session_id
  where o.id = p_order_id
  limit 1;

  if v_source_session_id is null then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if v_order_closed_at is not null or v_order_status <> 'open' then
    raise exception 'ORDER_NOT_OPEN';
  end if;

  if v_source_origin <> 'manual' then
    raise exception 'ORDER_NOT_MANUAL';
  end if;

  select z.business_id
    into v_target_business_id
  from public.dining_tables dt
  join public.zones z on z.id = dt.zone_id
  where dt.id = p_table_id
  limit 1;

  if v_target_business_id is null then
    raise exception 'TABLE_NOT_FOUND';
  end if;

  if v_user_id is not null
     and not public.user_has_business_access(v_user_id, v_target_business_id) then
    raise exception 'ACCESS_DENIED';
  end if;

  select ts.id
    into v_existing_target_session
  from public.table_sessions ts
  where ts.table_id = p_table_id
    and ts.closed_at is null
  order by ts.opened_at desc
  limit 1;

  if v_existing_target_session is not null then
    select count(*)
      into v_existing_open_orders
    from public.orders o
    where o.session_id = v_existing_target_session
      and o.closed_at is null
      and o.status_ext not in ('paid', 'void');

    if v_existing_open_orders > 0 then
      raise exception 'TARGET_TABLE_OCCUPIED';
    end if;

    v_new_session_id := v_existing_target_session;

    update public.table_sessions
       set origin = 'dine_in',
           people_count = greatest(1, coalesce(v_source_people, 1)),
           waiter_user_id = coalesce(v_source_waiter, waiter_user_id, v_user_id),
           customer_id = v_source_customer_id,
           customer_name = v_source_customer_name
     where id = v_new_session_id;
  else
    insert into public.table_sessions(
      table_id,
      opened_by,
      origin,
      waiter_user_id,
      people_count,
      customer_id,
      customer_name,
      business_id
    ) values (
      p_table_id,
      coalesce(v_user_id, v_source_opened_by),
      'dine_in',
      coalesce(v_source_waiter, v_user_id, v_source_opened_by),
      greatest(1, coalesce(v_source_people, 1)),
      v_source_customer_id,
      v_source_customer_name,
      v_target_business_id
    )
    returning id into v_new_session_id;
  end if;

  update public.orders
     set session_id = v_new_session_id
   where id = p_order_id;

  select count(*)
    into v_remaining_source_open_orders
  from public.orders o
  where o.session_id = v_source_session_id
    and o.closed_at is null
    and o.status_ext not in ('paid', 'void');

  if v_remaining_source_open_orders = 0 then
    update public.table_sessions
       set closed_at = now()
     where id = v_source_session_id
       and closed_at is null;
  end if;

  update public.dining_tables
     set state = 'occupied'
   where id = p_table_id;

  if v_source_table_id is not null then
    update public.dining_tables
       set state = 'available'
     where id = v_source_table_id
       and code not in ('manual', 'quick')
       and not exists (
         select 1
         from public.table_sessions ts
         where ts.table_id = v_source_table_id
           and ts.closed_at is null
       );
  end if;

  return jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'session_id', v_new_session_id,
    'table_id', p_table_id
  );
end;
$$;


ALTER FUNCTION public.fn_assign_manual_order_to_table(p_order_id uuid, p_table_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_check_max_checks(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_max_checks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (select count(*) from public.order_checks where order_id=new.order_id) >= 5 then
    raise exception 'Max 5 checks per order';
  end if;
  return new;
end $$;


