--
-- Name: fn_close_cash_session(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_cash_session(p_session_id uuid, p_end_amount numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_start_amount numeric := 0;
  v_total_sales numeric := 0;
  v_total_deposits numeric := 0;
  v_total_withdrawals numeric := 0;
  v_total_expenses numeric := 0;
  v_expected_cash numeric := 0;
  v_difference numeric := 0;
begin
  select coalesce(start_amount, 0)
    into v_start_amount
  from public.cash_register_sessions
  where id = p_session_id;

  if not found then
    raise exception 'SESSION_NOT_FOUND';
  end if;

  select coalesce(sum(amount), 0)
    into v_total_sales
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'sale';

  select coalesce(sum(amount), 0)
    into v_total_deposits
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'deposit';

  select coalesce(sum(amount), 0)
    into v_total_withdrawals
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'withdrawal';

  select coalesce(sum(amount), 0)
    into v_total_expenses
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'expense';

  v_expected_cash :=
    v_start_amount +
    v_total_sales +
    v_total_deposits -
    v_total_withdrawals -
    v_total_expenses;

  v_difference := p_end_amount - v_expected_cash;

  update public.cash_register_sessions
  set closed_at = now(),
      end_amount = p_end_amount,
      difference = v_difference,
      status = 'closed',
      notes = p_notes
  where id = p_session_id;

  return jsonb_build_object(
    'success', true,
    'difference', v_difference,
    'expected', v_expected_cash,
    'expected_amount', v_expected_cash,
    'expected_cash', v_expected_cash,
    'start_amount', v_start_amount,
    'total_sales', v_total_sales,
    'total_deposits', v_total_deposits,
    'total_withdrawals', v_total_withdrawals,
    'total_expenses', v_total_expenses
  );
end;
$$;


ALTER FUNCTION public.fn_close_cash_session(p_session_id uuid, p_end_amount numeric, p_notes text) OWNER TO postgres;

--
-- Name: fn_close_order_and_table(uuid, public.order_status); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_order_and_table(p_order_id uuid, p_status public.order_status) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session uuid;
  v_open_count int;
  v_table_id uuid;
begin
  update public.orders
  set status_ext = p_status,
      closed_at = now()
  where id = p_order_id;

  select session_id into v_session from public.orders where id = p_order_id;
  select table_id into v_table_id from public.table_sessions where id = v_session;

  select count(*) into v_open_count
  from public.orders
  where session_id = v_session
    and closed_at is null
    and status_ext not in ('paid', 'void');

  if coalesce(v_open_count, 0) = 0 then
    update public.table_sessions
    set closed_at = now()
    where id = v_session and closed_at is null;

    if v_table_id is not null then
      update public.dining_tables
      set state = 'available'
      where id = v_table_id;
    end if;
  end if;
end;
$$;


ALTER FUNCTION public.fn_close_order_and_table(p_order_id uuid, p_status public.order_status) OWNER TO postgres;

--
-- Name: fn_compute_item_totals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_compute_item_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  mods_total numeric(12,2) := 0;
  v_origin public.order_origin;
  v_default_tax numeric := 0;
  v_service_enabled boolean := false;
  v_service_rate numeric := 0;
  v_tax_rate numeric := 0;
begin
  select coalesce(sum(price*qty),0)
    into mods_total
  from public.order_item_modifiers
  where item_id = coalesce(new.id, old.id);

  -- Resolver tasa de impuesto según origen de la orden y ajustes del negocio
  select
    ts.origin,
    coalesce(bs.default_tax_rate, 0),
    coalesce(bs.service_fee_enabled, false),
    coalesce(bs.service_fee_rate, 0)
  into v_origin, v_default_tax, v_service_enabled, v_service_rate
  from public.orders o
  join public.table_sessions ts on ts.id = o.session_id
  left join public.business_settings bs on bs.business_id = ts.business_id
  where o.id = new.order_id
  limit 1;

  if v_origin = 'quick' then
    v_tax_rate := coalesce(v_service_rate, 0);
  else
    v_tax_rate := coalesce(v_default_tax, 0) +
      (case when v_service_enabled then coalesce(v_service_rate, 0) else 0 end);
  end if;

  new.subtotal := round((new.unit_price*new.qty) + mods_total, 2);
  new.tax := round(new.subtotal * (v_tax_rate / 100.0), 2);
  new.total := new.subtotal - coalesce(new.discounts,0) + coalesce(new.tax,0);
  return new;
end $$;


ALTER FUNCTION public.fn_compute_item_totals() OWNER TO postgres;

