--
-- Name: fn_create_split_bill(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_split_bill(p_order_id uuid, p_number_of_checks integer) RETURNS SETOF public.order_checks
    LANGUAGE plpgsql
    AS $$
declare
    v_i int;
    v_max_pos int;
begin
    -- Get current max position, default to 0
    select coalesce(max(position), 0) into v_max_pos
    from order_checks
    where order_id = p_order_id;

    -- Insert N checks starting from max_pos + 1
    for v_i in 1..p_number_of_checks loop
        insert into order_checks (order_id, label, position)
        values (
            p_order_id, 
            'Cuenta ' || (v_max_pos + v_i), 
            (v_max_pos + v_i)
        );
    end loop;

    return query select * from order_checks where order_id = p_order_id order by position;
end;
$$;


ALTER FUNCTION public.fn_create_split_bill(p_order_id uuid, p_number_of_checks integer) OWNER TO postgres;

