--
-- Name: fn_get_cash_session_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_cash_session_summary(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_start_amount numeric := 0;
  v_opened_at timestamptz;
  v_cash_sales_net numeric := 0;
  v_total_deposits numeric := 0;
  v_total_withdrawals numeric := 0;
  v_total_expenses numeric := 0;
  v_expected_cash numeric := 0;
  v_paid_cash numeric := 0;
  v_expected_card numeric := 0;
  v_expected_transfer numeric := 0;
  v_total_sales_all_methods numeric := 0;
  v_transaction_count integer := 0;
  v_result jsonb;
begin
  select coalesce(s.start_amount, 0), s.opened_at
    into v_start_amount, v_opened_at
  from public.cash_register_sessions s
  where s.id = p_session_id;

  if not found then
    raise exception 'SESSION_NOT_FOUND';
  end if;

  select coalesce(sum(amount), 0)
    into v_cash_sales_net
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'sale';

  select coalesce(sum(amount), 0)
    into v_total_deposits
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'deposit';

  select coalesce(sum(amount), 0)
    into v_total_withdrawals
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'withdrawal';

  select coalesce(sum(amount), 0)
    into v_total_expenses
  from public.cash_transactions
  where session_id = p_session_id
    and type = 'expense';

  select
    coalesce(sum(
      case
        when pm.code = 'cash' or lower(coalesce(pm.name, '')) like '%efectivo%'
          then p.amount
        else 0
      end
    ), 0),
    coalesce(sum(
      case
        when pm.code = 'card' or lower(coalesce(pm.name, '')) like '%tarjet%'
          then p.amount
        else 0
      end
    ), 0),
    coalesce(sum(
      case
        when pm.code = 'transfer' or lower(coalesce(pm.name, '')) like '%transfer%'
          then p.amount
        else 0
      end
    ), 0),
    coalesce(sum(p.amount), 0),
    coalesce(count(*), 0)::int
    into v_paid_cash, v_expected_card, v_expected_transfer, v_total_sales_all_methods, v_transaction_count
  from public.payments p
  join public.payment_methods pm on pm.id = p.payment_method_id
  where p.session_id = p_session_id
    and p.status = 'completed';

  v_expected_cash :=
    v_start_amount +
    v_cash_sales_net +
    v_total_deposits -
    v_total_withdrawals -
    v_total_expenses;

  v_result := jsonb_build_object(
    'start_amount', v_start_amount,
    'opened_at', v_opened_at,
    'total_sales', v_cash_sales_net,
    'cash_sales_net', v_cash_sales_net,
    'total_sales_all_methods', v_total_sales_all_methods,
    'total_deposits', v_total_deposits,
    'total_withdrawals', v_total_withdrawals,
    'total_expenses', v_total_expenses,
    'total_income', (v_cash_sales_net + v_total_deposits),
    'total_outflows', (v_total_withdrawals + v_total_expenses),
    'expected_amount', v_expected_cash,
    'expected_cash', v_expected_cash,
    'expected_card', v_expected_card,
    'expected_transfer', v_expected_transfer,
    'expected_total', (v_expected_cash + v_expected_card + v_expected_transfer),
    'paid_cash', v_paid_cash,
    'transaction_count', v_transaction_count
  );

  return v_result;
end;
$$;


ALTER FUNCTION public.fn_get_cash_session_summary(p_session_id uuid) OWNER TO postgres;

--
-- Name: fn_get_or_create_check(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_or_create_check(p_order_id uuid, p_position integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_check_id uuid;
begin
  select id into v_check_id
  from public.order_checks
  where order_id = p_order_id and position = p_position;

  if v_check_id is null then
    insert into public.order_checks(order_id, label, position)
    values (p_order_id, 'C'||p_position::text, p_position)
    returning id into v_check_id;
  end if;

  return v_check_id;
end $$;


ALTER FUNCTION public.fn_get_or_create_check(p_order_id uuid, p_position integer) OWNER TO postgres;

--
-- Name: fn_get_or_create_virtual_table(uuid, public.order_origin); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_or_create_virtual_table(p_business_id uuid, p_origin public.order_origin) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_zone_name text :=
    case when p_origin = 'quick' then 'Ventas rapidas' else 'Ventas manuales' end;
  v_zone_sort int := case when p_origin = 'quick' then 901 else 900 end;
  v_table_code text := case when p_origin = 'quick' then 'quick' else 'manual' end;
  v_table_label text :=
    case when p_origin = 'quick' then 'Venta rapida auto' else 'Venta manual auto' end;
  v_zone_id uuid;
  v_table_id uuid;
begin
  select id
    into v_zone_id
  from public.zones
  where business_id = p_business_id
    and name = v_zone_name
  limit 1;

  if v_zone_id is null then
    begin
      insert into public.zones (business_id, name, sort_index, is_active)
      values (p_business_id, v_zone_name, v_zone_sort, true)
      returning id into v_zone_id;
    exception when unique_violation then
      select id
        into v_zone_id
      from public.zones
      where business_id = p_business_id
        and name = v_zone_name
      limit 1;
    end;
  end if;

  select id
    into v_table_id
  from public.dining_tables
  where zone_id = v_zone_id
    and code = v_table_code
  limit 1;

  if v_table_id is null then
    begin
      insert into public.dining_tables (
        zone_id, code, label, shape, state, capacity,
        pos_x, pos_y, width, height, rotation, is_active
      )
      values (
        v_zone_id,
        v_table_code,
        v_table_label,
        'square',
        'available',
        2,
        0, 0, 1, 1, 0, true
      )
      returning id into v_table_id;
    exception when unique_violation then
      select id
        into v_table_id
      from public.dining_tables
      where zone_id = v_zone_id
        and code = v_table_code
      limit 1;
    end;
  end if;

  return v_table_id;
end;
$$;


ALTER FUNCTION public.fn_get_or_create_virtual_table(p_business_id uuid, p_origin public.order_origin) OWNER TO postgres;

