--
-- Name: fn_move_item_to_check(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_move_item_to_check(p_item_id uuid, p_check_position integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order uuid;
  v_check uuid;
begin
  select order_id into v_order
  from public.order_items
  where id = p_item_id;

  if v_order is null then
    raise exception 'ITEM_NOT_FOUND';
  end if;

  v_check := public.fn_get_or_create_check(v_order, p_check_position);

  update public.order_items
  set check_id = v_check
  where id = p_item_id;

  perform public.fn_recalc_order_totals(v_order);
end $$;


