--
-- Name: fn_normalize_domain(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_normalize_domain() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
begin
  if new.domain is not null then
    -- quita http(s)://
    new.domain := regexp_replace(new.domain, '^https?://', '', 'i');
    -- quita todo lo que venga después de una /
    new.domain := regexp_replace(new.domain, '/.*$', '');
    -- quita espacios
    new.domain := regexp_replace(new.domain, '\s+', '', 'g');
    -- a minúsculas
    new.domain := lower(new.domain);
  end if;
  return new;
end;
$_$;


ALTER FUNCTION public.fn_normalize_domain() OWNER TO postgres;

--
-- Name: fn_oi_sync_qty_quantity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_oi_sync_qty_quantity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.qty is null and new.quantity is null then
    new.qty := 1;
  end if;

  new.quantity := coalesce(new.quantity, new.qty, 1);
  new.qty      := coalesce(new.qty,      new.quantity, 1);

  if new.qty <= 0 then
    new.qty := 1; new.quantity := 1;
  end if;

  return new;
end $$;


ALTER FUNCTION public.fn_oi_sync_qty_quantity() OWNER TO postgres;

--
-- Name: fn_open_cash_session(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_open_cash_session(p_cash_register_id uuid, p_user_id uuid, p_start_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_session_id UUID;
    v_existing_open UUID;
BEGIN
    SELECT id INTO v_existing_open FROM cash_register_sessions
    WHERE cash_register_id = p_cash_register_id AND status = 'open';

    IF v_existing_open IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'Caja ya esta abierta', 'session_id', v_existing_open);
    END IF;

    INSERT INTO cash_register_sessions (cash_register_id, user_id, start_amount, status)
    VALUES (p_cash_register_id, p_user_id, p_start_amount, 'open')
    RETURNING id INTO v_session_id;

    INSERT INTO cash_transactions (session_id, amount, type, description)
    VALUES (v_session_id, p_start_amount, 'deposit', 'Apertura de caja');

    RETURN jsonb_build_object('success', true, 'session_id', v_session_id);
END;
$$;


ALTER FUNCTION public.fn_open_cash_session(p_cash_register_id uuid, p_user_id uuid, p_start_amount numeric) OWNER TO postgres;

--
-- Name: fn_open_manual_or_quick(public.order_origin, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_open_manual_or_quick(p_origin public.order_origin, p_user_id uuid, p_people_count integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := coalesce(auth.uid(), p_user_id);
  v_business_id uuid;
  v_table_id uuid;
  v_session_id uuid;
  v_order_id uuid;
  v_existing_session uuid;
  v_open_order_id uuid;
begin
  if auth.uid() is not null and p_user_id is not null and p_user_id <> auth.uid() then
    raise exception 'INVALID_USER_CONTEXT';
  end if;

  if v_user_id is null then
    raise exception 'fn_open_manual_or_quick: user id is required';
  end if;

  if p_origin not in ('manual'::public.order_origin, 'quick'::public.order_origin) then
    raise exception 'ORIGIN_NOT_ALLOWED';
  end if;

  perform public.fn_require_open_cash_session(v_user_id);

  select business_id
    into v_business_id
  from public.user_businesses
  where user_id = v_user_id
  order by created_at
  limit 1;

  if v_business_id is null then
    select bid
      into v_business_id
    from public.current_user_business_ids() as bid
    limit 1;
  end if;

  if v_business_id is null then
    raise exception 'fn_open_manual_or_quick: no business found for user %', v_user_id;
  end if;

  v_table_id := public.fn_get_or_create_virtual_table(v_business_id, p_origin);

  select id
    into v_existing_session
  from public.table_sessions
  where table_id = v_table_id
    and closed_at is null
  limit 1;

  if v_existing_session is not null then
    for v_open_order_id in
      select id
      from public.orders
      where session_id = v_existing_session
        and status_ext = 'open'
    loop
      perform public.fn_close_order_and_table(v_open_order_id, 'void');
    end loop;

    update public.table_sessions
    set closed_at = now()
    where id = v_existing_session;
  end if;

  insert into public.table_sessions (table_id, opened_by, origin, waiter_user_id, people_count)
  values (v_table_id, v_user_id, p_origin, v_user_id, greatest(1, p_people_count))
  returning id into v_session_id;

  insert into public.orders (session_id, status_ext, subtotal, discounts, tax, total, total_amount)
  values (v_session_id, 'open', 0, 0, 0, 0, 0)
  returning id into v_order_id;

  insert into public.order_checks (order_id, label, position)
  values (v_order_id, 'C1', 1);

  return jsonb_build_object('session_id', v_session_id, 'order_id', v_order_id);
end;
$$;


ALTER FUNCTION public.fn_open_manual_or_quick(p_origin public.order_origin, p_user_id uuid, p_people_count integer) OWNER TO postgres;

--
-- Name: fn_open_table(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_open_table(p_table_id uuid, p_user_id uuid, p_people_count integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session_id uuid;
  v_order_id uuid;
  v_user_id uuid;
begin
  if auth.uid() is not null and p_user_id is not null and p_user_id <> auth.uid() then
    raise exception 'INVALID_USER_CONTEXT';
  end if;

  v_user_id := coalesce(auth.uid(), p_user_id);

  if v_user_id is null then
    raise exception 'USER_REQUIRED';
  end if;

  perform public.fn_require_open_cash_session(v_user_id);

  select id
    into v_session_id
  from public.table_sessions
  where table_id = p_table_id
    and closed_at is null
  order by opened_at desc
  limit 1;

  if v_session_id is null then
    insert into public.table_sessions(table_id, opened_by, origin, waiter_user_id, people_count)
    values (p_table_id, v_user_id, 'dine_in', v_user_id, greatest(1, p_people_count))
    returning id into v_session_id;
  end if;

  update public.dining_tables
     set state = 'occupied'
   where id = p_table_id;

  select id
    into v_order_id
  from public.orders
  where session_id = v_session_id
    and closed_at is null
    and status_ext not in ('paid', 'void')
  order by created_at desc
  limit 1;

  if v_order_id is null then
    insert into public.orders(session_id, status_ext, subtotal, discounts, tax, total, total_amount)
    values (v_session_id, 'open', 0, 0, 0, 0, 0)
    returning id into v_order_id;

    insert into public.order_checks(order_id, label, position)
    values (v_order_id, 'C1', 1);
  end if;

  return jsonb_build_object('session_id', v_session_id, 'order_id', v_order_id);
end;
$$;


ALTER FUNCTION public.fn_open_table(p_table_id uuid, p_user_id uuid, p_people_count integer) OWNER TO postgres;

--
-- Name: fn_pick_member_for_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pick_member_for_table(p_table_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with biz as (
    select z.business_id
    from public.dining_tables dt
    join public.zones z on z.id = dt.zone_id
    where dt.id = p_table_id
    limit 1
  ),
  pick_from_memberships as (
    select m.user_id
    from public.memberships m, biz
    where m.business_id = biz.business_id
      and coalesce(m.status, 'active') = 'active'
    order by
      case when coalesce(m.role::text,'staff') in ('owner','admin','manager') then 0 else 1 end,
      m.start_date nulls last
    limit 1
  ),
  pick_from_user_businesses as (
    select ub.user_id
    from public.user_businesses ub, biz
    where ub.business_id = biz.business_id
    order by
      case when coalesce(ub.role,'staff') in ('owner','admin','manager') then 0 else 1 end,
      ub.created_at nulls last
    limit 1
  )
  select coalesce(
    (select user_id from pick_from_memberships),
    (select user_id from pick_from_user_businesses)
  );
$$;


ALTER FUNCTION public.fn_pick_member_for_table(p_table_id uuid) OWNER TO postgres;

--
-- Name: payments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    order_id uuid,
    check_id uuid,
    fiscal_document_id uuid,
    payment_method_id uuid,
    amount numeric NOT NULL,
    reference text,
    change_amount numeric DEFAULT 0,
    status text DEFAULT 'completed'::text,
    processed_by uuid,
    session_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    customer_id uuid,
    customer_rnc text,
    CONSTRAINT payments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'refunded'::text, 'cancelled'::text])))
);


ALTER TABLE public.payments OWNER TO postgres;

--
-- Name: fn_process_payment(uuid, uuid, text, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_process_payment(p_order_id uuid, p_check_id uuid, p_payment_method_id text, p_amount numeric, p_reference text, p_customer_id uuid DEFAULT NULL::uuid, p_customer_rnc text DEFAULT NULL::text) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $_$
declare
  v_payment public.payments;
  v_business_id uuid;
  v_session_id uuid;
  v_payment_method_id uuid;
begin
  select session_id into v_session_id from public.orders where id = p_order_id;
  -- Get business_id from order->session->table->zone OR current user context
  -- Simplest is to fetch from order ownership, but here let's assume we can get it from context or passed.
  -- For now, we'll try to get it from table_session
  select z.business_id into v_business_id
  from public.orders o
  join public.table_sessions ts on o.session_id = ts.id
  join public.dining_tables dt on ts.table_id = dt.id
  join public.zones z on dt.zone_id = z.id
  where o.id = p_order_id;

  -- Resolver payment_method_id (uuid o code)
  if p_payment_method_id ~* '^[0-9a-f-]{36}$' then
    v_payment_method_id := p_payment_method_id::uuid;
  else
    select pm.id into v_payment_method_id
    from public.payment_methods pm
    where pm.business_id = v_business_id
      and pm.code = p_payment_method_id
      and pm.is_active = true
    limit 1;
  end if;

  if v_payment_method_id is null then
    raise exception 'Metodo de pago no valido: %', p_payment_method_id;
  end if;

  insert into public.payments(
    business_id, order_id, check_id, payment_method_id, amount, reference, status, session_id, created_at
  )
  values (
    v_business_id, p_order_id, p_check_id, v_payment_method_id, p_amount, p_reference, 'completed', v_session_id, now()
  )
  returning * into v_payment;

  perform public.fn_close_order_and_table(p_order_id, 'paid');

  return v_payment;
end;
$_$;


ALTER FUNCTION public.fn_process_payment(p_order_id uuid, p_check_id uuid, p_payment_method_id text, p_amount numeric, p_reference text, p_customer_id uuid, p_customer_rnc text) OWNER TO postgres;

--
-- Name: fn_process_payment_v2(uuid, uuid, text, numeric, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_process_payment_v2(p_order_id uuid, p_check_id uuid, p_payment_method_id text, p_amount numeric, p_reference text, p_customer_id uuid, p_customer_rnc text, p_cashier_session_id uuid) RETURNS json
    LANGUAGE plpgsql
    SET statement_timeout TO '60s'
    AS $_$
DECLARE
  v_payment_id uuid;
  v_business_id uuid;
  v_final_method_id uuid;
  v_payment_record json;
  v_open_items_count integer;
  v_is_uuid boolean;
BEGIN
  -- 1. Obtener business_id de la orden (via session)
  SELECT t.business_id INTO v_business_id
  FROM public.orders o
  JOIN public.table_sessions t ON o.session_id = t.id
  WHERE o.id = p_order_id;

  -- Fallback si no hay session (ej. venta rapida directa sin layout?)
  IF v_business_id IS NULL THEN
    -- Intentar buscar en user metadata o similar? 
    -- Por simplicidad, asumimos que orders SIEMPRE tiene session valida en este sistema.
    -- O buscamos en payment_methods si el ID paso directo?
    NULL; 
  END IF;

  -- 2. Resolver Payment Method ID
  -- Verificamos si es UUID
  v_is_uuid := (p_payment_method_id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$');
  
  IF v_is_uuid THEN
    v_final_method_id := p_payment_method_id::uuid;
  ELSE
    -- Buscar por code (ej 'cash', 'card')
    SELECT id INTO v_final_method_id
    FROM public.payment_methods
    WHERE business_id = v_business_id 
      AND code = p_payment_method_id
      AND is_active = true
    LIMIT 1;
    
    IF v_final_method_id IS NULL THEN
        RAISE EXCEPTION 'Método de pago no válido: %', p_payment_method_id;
    END IF;
  END IF;

  -- 3. Insertar Pago
  INSERT INTO public.payments (
    business_id,
    order_id,
    check_id,
    payment_method_id,
    amount,
    reference,
    customer_id,
    customer_rnc,
    processed_by,
    session_id, -- cashier session
    status,
    created_at
  ) VALUES (
    v_business_id,
    p_order_id,
    p_check_id,
    v_final_method_id,
    p_amount,
    p_reference,
    p_customer_id,
    p_customer_rnc,
    auth.uid(),
    p_cashier_session_id,
    'completed',
    NOW()
  )
  RETURNING id INTO v_payment_id;

  -- 4. Retornar el registro insertado (como JSON)
  SELECT row_to_json(p.*) INTO v_payment_record
  FROM public.payments p
  WHERE p.id = v_payment_id;

  -- 5. Actualizar Estado de Items / Checks
  IF p_check_id IS NOT NULL THEN
    -- Caso 1: Pago de una cuenta separada (Check)
    
    -- Marcar items del check como pagados (ignorando voids)
    UPDATE public.order_items
    SET status = 'paid'
    WHERE check_id = p_check_id 
      AND status != 'void'
      AND status != 'paid'; -- Evitar re-update innecesario

    -- Marcar check como cerrado
    UPDATE public.order_checks
    SET is_closed = true,
        closed_at = NOW()
    WHERE id = p_check_id;
    
  ELSE
    -- Caso 2: Pago de la orden completa (o sin especificar check)
    -- Asumimos que si no hay check_id, estamos pagando/cerrando lo que quede.
    
    UPDATE public.order_items
    SET status = 'paid'
    WHERE order_id = p_order_id
      AND status != 'void'
      AND status != 'paid';
      
  END IF;

  -- 6. Recalcular y Verificar Cierre de Orden
  -- (Opcional: triggers en order_items deberían recalcular subtotales de orden)
  
  -- Verificar si quedan items abiertos en TODA la orden
  SELECT count(*) INTO v_open_items_count
  FROM public.order_items
  WHERE order_id = p_order_id
    AND status NOT IN ('paid', 'void');

  IF v_open_items_count = 0 THEN
    -- Cerrar orden y mesa
    -- Usamos la función existente para consistencia
    PERFORM public.fn_close_order_and_table(p_order_id, 'paid');
  END IF;

  RETURN v_payment_record;
END;
$_$;


ALTER FUNCTION public.fn_process_payment_v2(p_order_id uuid, p_check_id uuid, p_payment_method_id text, p_amount numeric, p_reference text, p_customer_id uuid, p_customer_rnc text, p_cashier_session_id uuid) OWNER TO postgres;

--
-- Name: fn_process_payment_v3(uuid, uuid, text, numeric, text, uuid, text, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_process_payment_v3(p_order_id uuid, p_check_id uuid, p_payment_method_id text, p_amount numeric, p_reference text, p_customer_id uuid DEFAULT NULL::uuid, p_customer_rnc text DEFAULT NULL::text, p_cashier_session_id uuid DEFAULT NULL::uuid, p_change_amount numeric DEFAULT 0) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_payment public.payments;
  v_business_id uuid;
  v_table_session_id uuid;
  v_payment_method_id uuid;
  v_payment_method_code text;
  v_open_items_count bigint := 0;
  v_cash_in_drawer numeric := 0;
begin
  select o.session_id
    into v_table_session_id
  from public.orders o
  where o.id = p_order_id;

  if v_table_session_id is null then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  select ts.business_id
    into v_business_id
  from public.table_sessions ts
  where ts.id = v_table_session_id;

  if v_business_id is null then
    select bid
      into v_business_id
    from public.current_user_business_ids() as bid
    limit 1;
  end if;

  if v_business_id is null then
    raise exception 'BUSINESS_NOT_FOUND';
  end if;

  if p_cashier_session_id is null then
    raise exception 'CASH_SESSION_REQUIRED';
  end if;

  perform 1
  from public.cash_register_sessions s
  where s.id = p_cashier_session_id
    and s.status = 'open'
    and s.closed_at is null;

  if not found then
    raise exception 'CASH_SESSION_NOT_OPEN';
  end if;

  if p_payment_method_id ~* '^[0-9a-f-]{36}$' then
    select pm.id, pm.code
      into v_payment_method_id, v_payment_method_code
    from public.payment_methods pm
    where pm.id = p_payment_method_id::uuid
      and pm.is_active = true
    limit 1;
  else
    select pm.id, pm.code
      into v_payment_method_id, v_payment_method_code
    from public.payment_methods pm
    where pm.business_id = v_business_id
      and pm.code = p_payment_method_id
      and pm.is_active = true
    limit 1;
  end if;

  if v_payment_method_id is null then
    raise exception 'INVALID_PAYMENT_METHOD';
  end if;

  insert into public.payments(
    business_id,
    order_id,
    check_id,
    payment_method_id,
    amount,
    reference,
    change_amount,
    status,
    processed_by,
    session_id,
    customer_id,
    customer_rnc,
    created_at
  )
  values (
    v_business_id,
    p_order_id,
    p_check_id,
    v_payment_method_id,
    p_amount,
    p_reference,
    coalesce(p_change_amount, 0),
    'completed',
    auth.uid(),
    p_cashier_session_id,
    p_customer_id,
    p_customer_rnc,
    now()
  )
  returning * into v_payment;

  if p_check_id is not null then
    update public.order_items
    set status = 'paid'
    where order_id = p_order_id
      and check_id = p_check_id
      and status <> 'void';

    update public.order_checks
    set is_closed = true,
        closed_at = now()
    where id = p_check_id;

    select count(*)
      into v_open_items_count
    from public.order_items
    where order_id = p_order_id
      and status not in ('paid', 'void');

    if v_open_items_count = 0 then
      perform public.fn_close_order_and_table(p_order_id, 'paid');
    end if;
  else
    update public.order_items
    set status = 'paid'
    where order_id = p_order_id
      and status <> 'void';

    perform public.fn_close_order_and_table(p_order_id, 'paid');
  end if;

  if v_payment_method_code = 'cash' then
    v_cash_in_drawer := greatest(
      coalesce(p_amount, 0) - coalesce(p_change_amount, 0),
      0
    );

    if v_cash_in_drawer > 0 then
      insert into public.cash_transactions(
        session_id,
        amount,
        type,
        description,
        related_order_id
      )
      values (
        p_cashier_session_id,
        v_cash_in_drawer,
        'sale',
        'Venta ' || left(p_order_id::text, 8),
        p_order_id
      );
    end if;
  end if;

  return v_payment;
end;
$_$;


ALTER FUNCTION public.fn_process_payment_v3(p_order_id uuid, p_check_id uuid, p_payment_method_id text, p_amount numeric, p_reference text, p_customer_id uuid, p_customer_rnc text, p_cashier_session_id uuid, p_change_amount numeric) OWNER TO postgres;

--
-- Name: fn_recalc_order_totals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_recalc_order_totals(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  update public.orders o
  set subtotal = coalesce(s.subtotal,0),
      discounts = coalesce(s.discounts,0),
      tax = coalesce(s.tax,0),
      total = coalesce(s.total,0)
  from (
    select order_id,
           sum(subtotal) subtotal,
           sum(discounts) discounts,
           sum(tax) tax,
           sum(total) total
    from public.order_items
    where order_id = p_order_id
    group by order_id
  ) s
  where o.id = p_order_id;
end $$;


ALTER FUNCTION public.fn_recalc_order_totals(p_order_id uuid) OWNER TO postgres;

--
-- Name: fn_require_open_cash_session(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_require_open_cash_session(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session_id uuid;
begin
  select s.id
    into v_session_id
  from public.cash_register_sessions s
  where s.user_id = p_user_id
    and s.status = 'open'
    and s.closed_at is null
  order by s.opened_at desc
  limit 1;

  if v_session_id is null then
    raise exception 'CASH_SESSION_NOT_OPEN';
  end if;

  return v_session_id;
end;
$$;


ALTER FUNCTION public.fn_require_open_cash_session(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_start_preparing_order(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_start_preparing_order(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.order_items
  set status = 'preparing',
      started_at = now()
  where order_id = p_order_id
    and status in ('pending');
end;
$$;


ALTER FUNCTION public.fn_start_preparing_order(p_order_id uuid) OWNER TO postgres;

--
-- Name: fn_toggle_item_takeout(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_toggle_item_takeout(p_item_id uuid, p_takeout boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.order_items
  set is_takeout = p_takeout
  where id = p_item_id;
$$;


ALTER FUNCTION public.fn_toggle_item_takeout(p_item_id uuid, p_takeout boolean) OWNER TO postgres;

--
-- Name: fn_update_item_notes(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_item_notes(p_item_id uuid, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order_id uuid;
begin
  update public.order_items
     set notes = nullif(trim(coalesce(p_notes, '')), '')
   where id = p_item_id
   returning order_id into v_order_id;

  if v_order_id is null then
    raise exception 'ITEM_NOT_FOUND';
  end if;

  perform public.fn_recalc_order_totals(v_order_id);
end;
$$;


ALTER FUNCTION public.fn_update_item_notes(p_item_id uuid, p_notes text) OWNER TO postgres;

--
-- Name: fn_update_item_qty(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_item_qty(p_item_id uuid, p_qty numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order_id uuid;
  v_qty numeric(10,3);
begin
  v_qty := greatest(coalesce(p_qty, 1), 1);

  update public.order_items
     set qty = v_qty,
         quantity = greatest(1, round(v_qty)::int)
   where id = p_item_id
   returning order_id into v_order_id;

  if v_order_id is null then
    raise exception 'ITEM_NOT_FOUND';
  end if;

  perform public.fn_recalc_order_totals(v_order_id);
end;
$$;


ALTER FUNCTION public.fn_update_item_qty(p_item_id uuid, p_qty numeric) OWNER TO postgres;

--
-- Name: fn_user_effective_permissions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_user_effective_permissions(p_business_id uuid, p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_employee_id uuid;
  v_permissions text[];
BEGIN
  -- 1. Obtener el ID del empleado para este usuario y negocio
  SELECT id INTO v_employee_id
  FROM public.employees
  WHERE user_id = p_user_id AND business_id = p_business_id;

  -- Si no es empleado, retornar array vacío
  IF v_employee_id IS NULL THEN
    RETURN '[]'::json;
  END IF;

  -- 2. Obtener todos los permisos efectivos (suma de todos sus roles)
  SELECT array_agg(DISTINCT rp.permission_key)
  INTO v_permissions
  FROM public.employee_roles er
  JOIN public.role_permissions rp ON rp.role_id = er.role_id
  WHERE er.employee_id = v_employee_id;

  -- Retornar como JSON (si es null, devolver array vacío)
  RETURN to_json(COALESCE(v_permissions, '{}'::text[]));
END;
$$;


ALTER FUNCTION public.fn_user_effective_permissions(p_business_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_user_in_business(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_user_in_business(p_business_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM user_businesses 
        WHERE business_id = p_business_id AND user_id = auth.uid()
    ) OR EXISTS (
        SELECT 1 FROM employees 
        WHERE business_id = p_business_id AND user_id = auth.uid()
    );
END;
$$;


ALTER FUNCTION public.fn_user_in_business(p_business_id uuid) OWNER TO postgres;

--
-- Name: generate_ncf(uuid, public.ncf_type); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_ncf(_business_id uuid, _ncf_type public.ncf_type) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  _sequence RECORD;
  _new_number bigint;
  _ncf text;
BEGIN
  SELECT * INTO _sequence
  FROM public.ncf_sequences
  WHERE business_id = _business_id
    AND ncf_type = _ncf_type
    AND is_active = true
    AND current_number < range_end
    AND (expiration_date IS NULL OR expiration_date > CURRENT_DATE)
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No hay secuencia NCF disponible para tipo %', _ncf_type;
  END IF;
  
  _new_number := _sequence.current_number + 1;
  
  UPDATE public.ncf_sequences
  SET current_number = _new_number
  WHERE id = _sequence.id;
  
  _ncf := _sequence.prefix || LPAD(_new_number::text, 8, '0');
  
  RETURN _ncf;
END;
$$;


ALTER FUNCTION public.generate_ncf(_business_id uuid, _ncf_type public.ncf_type) OWNER TO postgres;

--
-- Name: get_employee_permissions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_employee_permissions(p_employee_id uuid) RETURNS TABLE(permission_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT p.code
  FROM public.permissions p
  WHERE p.id IN (
    SELECT rp.permission_id
    FROM public.employee_roles er
    JOIN public.role_permissions rp ON rp.role_id = er.role_id
    WHERE er.employee_id = p_employee_id AND rp.allow = true
    UNION
    SELECT upo.permission_id
    FROM public.user_permission_overrides upo
    WHERE upo.employee_id = p_employee_id AND upo.allow = true
  )
  AND p.id NOT IN (
    SELECT upo.permission_id
    FROM public.user_permission_overrides upo
    WHERE upo.employee_id = p_employee_id AND upo.allow = false
  );
END;
$$;


ALTER FUNCTION public.get_employee_permissions(p_employee_id uuid) OWNER TO postgres;

--
-- Name: get_table_live(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_live(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_order_id uuid;
  v_order jsonb;
  v_checks jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;
begin
  select z.business_id
    into v_business_id
  from public.dining_tables dt
  join public.zones z on z.id = dt.zone_id
  where dt.id = p_table_id
  limit 1;

  if v_business_id is null then
    raise exception 'TABLE_NOT_FOUND';
  end if;

  if auth.uid() is not null
     and not public.user_has_business_access(auth.uid(), v_business_id) then
    raise exception 'ACCESS_DENIED';
  end if;

  select o.id
    into v_order_id
  from public.table_sessions ts
  join public.orders o on o.session_id = ts.id
  where ts.table_id = p_table_id
    and ts.closed_at is null
    and o.closed_at is null
    and o.status_ext not in ('paid', 'void')
  order by o.created_at desc
  limit 1;

  if v_order_id is null then
    return null;
  end if;

  select to_jsonb(x)
    into v_order
  from (
    select
      o.id,
      o.session_id,
      o.status_ext,
      o.subtotal,
      o.discounts,
      o.service_fee,
      o.tax,
      o.total,
      o.created_at
    from public.orders o
    where o.id = v_order_id
  ) x;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'id', oc.id,
               'label', oc.label,
               'position', oc.position,
               'subtotal', oc.subtotal,
               'discounts', oc.discounts,
               'tax', oc.tax,
               'total', oc.total
             )
             order by oc.position
           ),
           '[]'::jsonb
         )
    into v_checks
  from public.order_checks oc
  where oc.order_id = v_order_id;

  select coalesce(
           jsonb_agg(to_jsonb(oi) order by oi.created_at),
           '[]'::jsonb
         )
    into v_items
  from public.order_items oi
  where oi.order_id = v_order_id
    and oi.status not in ('paid', 'void');

  return jsonb_build_object(
    'order', v_order,
    'checks', v_checks,
    'items', v_items
  );
end;
$$;


ALTER FUNCTION public.get_table_live(p_table_id uuid) OWNER TO postgres;

