--
-- Name: v_employees_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_employees_summary AS
 SELECT id,
    business_id,
    user_id,
    first_name,
    last_name,
    email,
    phone,
    national_id,
    gender,
    address,
    status,
    hire_date,
    contract_type,
    department,
    "position",
    work_schedule,
    salary_base,
    pay_frequency,
    bank_name,
    bank_account,
    emergency_name,
    emergency_relation,
    emergency_phone,
    pin,
    created_at,
    updated_at,
    COALESCE(( SELECT json_agg(r.name) AS json_agg
           FROM (public.employee_roles er
             JOIN public.roles r ON ((r.id = er.role_id)))
          WHERE (er.employee_id = e.id)), '[]'::json) AS roles
   FROM public.employees e;


ALTER VIEW public.v_employees_summary OWNER TO postgres;

--
-- Name: v_kitchen_items; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_kitchen_items AS
 SELECT oi.id,
    oi.order_id,
    oi.product_id,
    mi.name AS product_name,
    oi.qty,
    oi.status,
    oi.notes,
    oi.created_at,
    COALESCE(z.business_id, mi.business_id) AS business_id,
    dt.label AS table_name,
    z.name AS zone_name
   FROM (((((public.order_items oi
     JOIN public.orders o ON ((oi.order_id = o.id)))
     LEFT JOIN public.menu_items mi ON ((oi.product_id = mi.id)))
     LEFT JOIN public.table_sessions ts ON ((o.session_id = ts.id)))
     LEFT JOIN public.dining_tables dt ON ((ts.table_id = dt.id)))
     LEFT JOIN public.zones z ON ((dt.zone_id = z.id)));


ALTER VIEW public.v_kitchen_items OWNER TO postgres;

--
-- Name: v_menu_items_list; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_menu_items_list WITH (security_invoker='on') AS
 SELECT i.id,
    i.business_id,
    i.name,
    i.description,
    i.category_id,
    c.name AS category_name,
    i.price,
    i.sku,
    i.prep_minutes,
    i.has_variants,
    i.is_active,
    i.image_url,
    i.created_at,
    l.menu_id,
    m.name AS menu_name,
    l."position"
   FROM (((public.menu_items i
     LEFT JOIN LATERAL ( SELECT l1.menu_id,
            l1."position"
           FROM public.menu_item_links l1
          WHERE (l1.item_id = i.id)
          ORDER BY l1."position"
         LIMIT 1) l ON (true))
     LEFT JOIN public.menus m ON ((m.id = l.menu_id)))
     LEFT JOIN public.categories c ON ((c.id = i.category_id)));


ALTER VIEW public.v_menu_items_list OWNER TO postgres;

--
-- Name: v_menus_with_counts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_menus_with_counts WITH (security_invoker='on') AS
 SELECT id,
    business_id,
    name,
    is_active,
    created_at,
    ( SELECT (count(*))::integer AS count
           FROM (public.menu_item_links mil
             JOIN public.menu_items mi ON ((mi.id = mil.item_id)))
          WHERE (mil.menu_id = m.id)) AS items_count
   FROM public.menus m;


ALTER VIEW public.v_menus_with_counts OWNER TO postgres;

--
-- Name: v_order_detail; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_order_detail WITH (security_invoker='on') AS
 SELECT o.id AS order_id,
    oc.id AS check_id,
    oc."position" AS check_pos,
    oc.label AS check_label,
    oi.id AS item_id,
    oi.product_id,
    oi.product_name,
    oi.qty,
    oi.unit_price,
    oi.is_takeout,
    oi.status,
    oi.notes,
    oi.subtotal,
    oi.discounts,
    oi.tax,
    oi.total,
    o.subtotal AS order_subtotal,
    o.discounts AS order_discounts,
    o.tax AS order_tax,
    o.total AS order_total,
    o.status_ext
   FROM ((public.orders o
     LEFT JOIN public.order_checks oc ON ((oc.order_id = o.id)))
     LEFT JOIN public.order_items oi ON (((oi.order_id = o.id) AND (oi.check_id = oc.id))));


ALTER VIEW public.v_order_detail OWNER TO postgres;

--
-- Name: v_table_live; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_table_live AS
SELECT
    NULL::uuid AS table_id,
    NULL::uuid AS session_id,
    NULL::uuid AS order_id,
    NULL::public.order_status AS status_ext,
    NULL::numeric(12,2) AS subtotal,
    NULL::numeric(12,2) AS discounts,
    NULL::numeric(12,2) AS service_fee,
    NULL::numeric(12,2) AS tax,
    NULL::numeric(12,2) AS total,
    NULL::bigint AS items_count,
    NULL::timestamp with time zone AS last_item_at;


ALTER VIEW public.v_table_live OWNER TO postgres;

--
-- Name: v_zone_table_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_zone_table_status AS
 SELECT t.id AS table_id,
    z.id AS zone_id,
    z.name AS zone_name,
    z.business_id,
    t.code,
    t.label,
    t.shape,
    t.capacity,
    t.state,
    s.id AS session_id,
    s.opened_by,
    s.opened_at,
        CASE
            WHEN ((s.opened_at IS NOT NULL) AND (s.closed_at IS NULL)) THEN ((EXTRACT(epoch FROM (now() - s.opened_at)))::integer / 60)
            ELSE NULL::integer
        END AS minutes_open,
    COALESCE(( SELECT count(*) AS count
           FROM public.orders o
          WHERE ((o.session_id = s.id) AND (o.closed_at IS NULL) AND (o.status_ext <> ALL (ARRAY['paid'::public.order_status, 'void'::public.order_status])))), (0)::bigint) AS orders_count,
    s.people_count,
    COALESCE(( SELECT sum(((oi.subtotal + oi.tax) - oi.discounts)) AS sum
           FROM (public.orders o
             JOIN public.order_items oi ON ((oi.order_id = o.id)))
          WHERE ((o.session_id = s.id) AND (o.closed_at IS NULL) AND (o.status_ext <> ALL (ARRAY['paid'::public.order_status, 'void'::public.order_status])) AND (oi.status <> ALL (ARRAY['paid'::public.item_status, 'void'::public.item_status])))), (0)::numeric) AS total,
    COALESCE(( SELECT count(*) AS count
           FROM (public.order_items oi
             JOIN public.orders o2 ON ((oi.order_id = o2.id)))
          WHERE ((o2.session_id = s.id) AND (o2.closed_at IS NULL) AND (o2.status_ext <> ALL (ARRAY['paid'::public.order_status, 'void'::public.order_status])) AND (oi.status <> ALL (ARRAY['paid'::public.item_status, 'void'::public.item_status])))), (0)::bigint) AS items_count
   FROM ((public.dining_tables t
     JOIN public.zones z ON ((z.id = t.zone_id)))
     LEFT JOIN LATERAL ( SELECT s2.id,
            s2.table_id,
            s2.opened_by,
            s2.opened_at,
            s2.closed_at,
            s2.customer_name,
            s2.note,
            s2.origin,
            s2.waiter_user_id,
            s2.people_count,
            s2.business_id
           FROM public.table_sessions s2
          WHERE ((s2.table_id = t.id) AND (s2.closed_at IS NULL))
          ORDER BY s2.opened_at DESC
         LIMIT 1) s ON (true));


ALTER VIEW public.v_zone_table_status OWNER TO postgres;

--
-- Name: v_zone_table_status2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_zone_table_status2 WITH (security_invoker='on') AS
 SELECT t.id AS table_id,
    z.id AS zone_id,
    z.name AS zone_name,
    t.code,
    t.label,
    t.state,
    s.id AS session_id,
    s.waiter_user_id,
    s.opened_at,
        CASE
            WHEN (s.closed_at IS NULL) THEN ((EXTRACT(epoch FROM (now() - s.opened_at)))::integer / 60)
            ELSE NULL::integer
        END AS minutes_open,
    ( SELECT count(*) AS count
           FROM public.orders o
          WHERE ((o.session_id = s.id) AND (o.status_ext = 'open'::public.order_status))) AS open_orders
   FROM ((public.dining_tables t
     JOIN public.zones z ON ((z.id = t.zone_id)))
     LEFT JOIN LATERAL ( SELECT s2.id,
            s2.table_id,
            s2.opened_by,
            s2.opened_at,
            s2.closed_at,
            s2.customer_name,
            s2.note,
            s2.origin,
            s2.waiter_user_id,
            s2.people_count
           FROM public.table_sessions s2
          WHERE ((s2.table_id = t.id) AND (s2.closed_at IS NULL))
          ORDER BY s2.opened_at DESC
         LIMIT 1) s ON (true));


ALTER VIEW public.v_zone_table_status2 OWNER TO postgres;

