--
-- Name: v_table_live _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.v_table_live AS
 SELECT ts.table_id,
    ts.id AS session_id,
    o.id AS order_id,
    o.status_ext,
    o.subtotal,
    o.discounts,
    o.service_fee,
    o.tax,
    o.total,
    count(oi.id) AS items_count,
    max(oi.created_at) AS last_item_at
   FROM ((public.table_sessions ts
     JOIN public.orders o ON ((o.session_id = ts.id)))
     LEFT JOIN public.order_items oi ON ((oi.order_id = o.id)))
  WHERE (ts.closed_at IS NULL)
  GROUP BY ts.table_id, ts.id, o.id;


