--
-- Name: fn_get_order_bundle(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION public.fn_get_order_bundle(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payload jsonb;
begin
  if p_order_id is null then
    raise exception 'ORDER_ID_REQUIRED';
  end if;

  with target_order as (
    select o.*
    from public.orders o
    where o.id = p_order_id
    limit 1
  ),
  order_customer as (
    select
      ts.customer_id,
      ts.customer_name
    from target_order o
    join public.table_sessions ts on ts.id = o.session_id
  )
  select jsonb_build_object(
    'order',
      (
        select to_jsonb(o)
        from target_order o
      ),
    'checks',
      coalesce(
        (
          select jsonb_agg(to_jsonb(oc) order by oc.position)
          from public.order_checks oc
          where oc.order_id = p_order_id
        ),
        '[]'::jsonb
      ),
    'items',
      coalesce(
        (
          select jsonb_agg(to_jsonb(oi) order by oi.created_at, oi.id)
          from public.order_items oi
          where oi.order_id = p_order_id
            and oi.status not in ('paid'::public.item_status, 'void'::public.item_status)
        ),
        '[]'::jsonb
      ),
    'customer_id',
      (
        select customer_id
        from order_customer
        limit 1
      ),
    'customer_name',
      (
        select customer_name
        from order_customer
        limit 1
      )
  )
  into v_payload;

  if v_payload is null or (v_payload -> 'order') is null then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  return v_payload;
end;
$$;


ALTER FUNCTION public.fn_get_order_bundle(p_order_id uuid) OWNER TO postgres;
GRANT ALL ON FUNCTION public.fn_get_order_bundle(p_order_id uuid) TO anon;
GRANT ALL ON FUNCTION public.fn_get_order_bundle(p_order_id uuid) TO authenticated;
GRANT ALL ON FUNCTION public.fn_get_order_bundle(p_order_id uuid) TO service_role;

